def choose_move(observation):
    # Defensive defaults
    # Try common keys for position and goal in a robust way
    # observation might include: "self_position" or "pos", "targets", "enemy", "resource", "goal", etc.
    x = observation.get("self_x", observation.get("x", None))
    y = observation.get("self_y", observation.get("y", None))

    # Fallback to a generic encoded position if provided as a tuple/list
    if x is None or y is None:
        pos = observation.get("self_position", observation.get("position", None))
        if isinstance(pos, (list, tuple)) and len(pos) >= 2:
            x, y = pos[0], pos[1]

    # If still not available, default to (0,0)
    if x is None or y is None:
        x, y = 0, 0

    # Try to infer a target direction from possible goals/resources/enemies
    dx = 0
    dy = 0

    # Resource collection: move toward closest resource if available
    res = observation.get("resources", None)
    if res and isinstance(res, (list, tuple)):
        # pick resource with smallest distance by a heuristic key if coordinates present
        # Look for resource coordinates
        best = None
        best_dist = None
        for r in res:
            if isinstance(r, dict):
                rx = r.get("x", None)
                ry = r.get("y", None)
            elif isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
            else:
                continue
            if rx is None or ry is None:
                continue
            dist = (rx - x) * (rx - x) + (ry - y) * (ry - y)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            if best[0] > x:
                dx = +1
            elif best[0] < x:
                dx = -1
            if best[1] > y:
                dy = +1
            elif best[1] < y:
                dy = -1
            # clamp to [-1,1]
            dx = max(-1, min(1, dx))
            dy = max(-1, min(1, dy))
            return [dx, dy]

    # Pursuit/Evasion: move toward closest opponent if available
    enemies = observation.get("enemies", None)
    if enemies and isinstance(enemies, (list, tuple)):
        best = None
        best_dist = None
        for e in enemies:
            if isinstance(e, dict):
                ex = e.get("x", None)
                ey = e.get("y", None)
            elif isinstance(e, (list, tuple)) and len(e) >= 2:
                ex, ey = e[0], e[1]
            else:
                continue
            if ex is None or ey is None:
                continue
            dist = (ex - x) * (ex - x) + (ey - y) * (ey - y)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best = (ex, ey)
        if best is not None:
            if best[0] > x:
                dx = +1
            elif best[0] < x:
                dx = -1
            if best[1] > y:
                dy = +1
            elif best[1] < y:
                dy = -1
            dx = max(-1, min(1, dx))
            dy = max(-1, min(1, dy))
            return [dx, dy]

    # Territory control / defensive stance: try to stay near center if known
    center = observation.get("center", None)
    if isinstance(center, (list, tuple)) and len(center) >= 2:
        cx, cy = center[0], center[1]
        if cx > x:
            dx = +1
        elif cx < x:
            dx = -1
        if cy > y:
            dy = +1
        elif cy < y:
            dy = -1
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        return [dx, dy]

    # If nothing actionable, stay still
    return [0, 0]

